// Minimal AWS CDK (TypeScript) snippet to create a budget and a stop rule
import * as cdk from 'aws-cdk-lib';
import * as budgets from 'aws-cdk-lib/aws-budgets';
import * as events from 'aws-cdk-lib/aws-events';
import * as targets from 'aws-cdk-lib/aws-events-targets';
import * as lambda from 'aws-cdk-lib/aws-lambda';

class CostGuardStack extends cdk.Stack {
  constructor(scope: cdk.App, id: string) {
    super(scope, id);

    // budget for the account
    new budgets.CfnBudget(this, 'SAPBudget', {
      budget: {
        budgetLimit: { amount: 100, unit: 'USD' },
        budgetName: 'SAPHANA-Prod-Budget',
        timeUnit: 'MONTHLY',
        costFilters: { Service: ['AmazonEC2'] }
      }
    });

